-- Run with Supabase execute_sql or psql as project administrator. ALL test data rolls back.
begin;
create temp table assertions(name text primary key,passed boolean not null);
grant select,insert on assertions to authenticated,anon;
create function pg_temp.ok(test_name text,condition boolean) returns void language plpgsql as $$begin
 if condition is distinct from true then raise exception 'FAILED: %',test_name;end if;
 insert into assertions values(test_name,true);
end $$;
create function pg_temp.denied(sql_text text,expected text) returns boolean language plpgsql as $$begin
 execute sql_text;return false;
 exception when others then return position(lower(expected) in lower(sqlerrm))>0;
end $$;
insert into auth.users(id,aud,role,email) values('aa000000-0000-4000-8000-000000000001','authenticated','authenticated','synthetic-test@courtside.example.invalid'),('aa000000-0000-4000-8000-000000000002','authenticated','authenticated','synthetic-other@courtside.example.invalid');
select set_config('request.jwt.claims','{"sub":"aa000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
do $$
declare l uuid;created jsonb;s jsonb;result jsonb;tid uuid;player_id uuid;proposal_id uuid;draft_id uuid;published_id uuid;sheet_id uuid;g jsonb;fixtures jsonb;bad jsonb;locked jsonb;future jsonb;extraction jsonb;first_rating int;queue jsonb;vrecord jsonb;candidate jsonb;le jsonb;
begin
 created:=public.create_demo();l:=(created->>'id')::uuid;perform set_config('test.league',l::text,true);
 s:=public.league_snapshot(l,false);
 perform pg_temp.ok('authenticated isolated demo',s->>'role'='admin' and jsonb_array_length(s->'teams')=12);
 perform pg_temp.ok('private demo hidden from directory',not exists(select 1 from public.public_leagues() where id=l));
 perform pg_temp.ok('direct writes denied',pg_temp.denied('update public.teams set rating=9999','permission denied'));
 result:=public.league_command(l,'register_team','{"name":"Test Comets","assessment":{"experience":3,"yearsTogether":2,"practicesPerWeek":2,"notes":"Synthetic"},"phone":"","sms_consent":false,"explanation":"Test rubric"}');tid:=(result->>'id')::uuid;
 perform pg_temp.ok('questionnaire rating deterministic',(select rating=1105 and status='pending' from public.teams where id=tid));
 perform public.league_command(l,'approve_team',jsonb_build_object('team_id',tid));
 perform pg_temp.ok('placement approval',(select status='approved' and division_id is not null from public.teams where id=tid));
 result:=public.league_command(l,'add_player',jsonb_build_object('team_id',tid,'display_name','Fictional Player','jersey','7','birth_date','2012-09-02','guardian_consent',true));player_id:=(result->>'id')::uuid;
 perform public.league_command(l,'verify_player',jsonb_build_object('player_id',player_id));
 perform pg_temp.ok('age cutoff eligibility',(select eligibility_status='verified' from public.players where id=player_id));
 result:=public.league_command(l,'add_player',jsonb_build_object('team_id',tid,'display_name','Fictional Older Player','jersey','8','birth_date','2012-09-01','guardian_consent',true));player_id:=(result->>'id')::uuid;
 perform public.league_command(l,'verify_player',jsonb_build_object('player_id',player_id));
 perform pg_temp.ok('over-age player blocked',(select eligibility_status='ineligible' from public.players where id=player_id));
 result:=public.league_command(l,'add_player',jsonb_build_object('team_id',tid,'display_name','Fictional No Consent','jersey','9','birth_date','2013-02-03','guardian_consent',false));player_id:=(result->>'id')::uuid;
 perform public.league_command(l,'verify_player',jsonb_build_object('player_id',player_id));
 perform pg_temp.ok('guardian consent required',(select eligibility_status='ineligible' from public.players where id=player_id));
 perform public.league_command(l,'propose_balance');s:=public.league_snapshot(l,false);
 perform pg_temp.ok('evidence-based proposal only',jsonb_array_length(s->'proposals')=1 and s#>>'{proposals,0,evidence,wins}'='3');proposal_id:=(s#>>'{proposals,0,id}')::uuid;
 perform public.league_command(l,'decide_proposal',jsonb_build_object('proposal_id',proposal_id,'approve',false));
 perform pg_temp.ok('rejected approval leaves placement unchanged',(public.league_snapshot(l,false)#>>'{proposals,0,status}')='rejected');
 perform public.league_command(l,'propose_balance');s:=public.league_snapshot(l,false);
 -- Snapshot contains all versions; reference demo currently has one published version.
 select coalesce(jsonb_agg(f),'[]') into locked from jsonb_array_elements(s->'fixtures') f where exists(select 1 from jsonb_array_elements(s->'games') gg where gg->>'id'=f->>'game_id' and gg->>'status'='confirmed');
 select coalesce(jsonb_agg(f),'[]') into future from jsonb_array_elements(s->'fixtures') f where (f->>'starts_at')::timestamptz>now();
 fixtures:=locked||future;
 result:=public.league_command(l,'draft_schedule',jsonb_build_object('base_revision',s#>'{league,revision}','data_revision',s#>'{league,data_revision}','explanation','Integration test schedule','fixtures',fixtures));draft_id:=(result->>'id')::uuid;
 perform public.league_command(l,'reject_schedule',jsonb_build_object('version_id',draft_id));
 perform pg_temp.ok('rejected schedule cannot publish',pg_temp.denied(format('select public.league_command(%L,''publish_schedule'',%L::jsonb)',l,jsonb_build_object('version_id',draft_id)),'Draft schedule not found'));
 bad:=locked||jsonb_build_array(future->0,jsonb_set(jsonb_set(jsonb_set(future->1,'{court_id}',future#>'{0,court_id}'),'{starts_at}',future#>'{0,starts_at}'),'{ends_at}',future#>'{0,ends_at}'));
 perform pg_temp.ok('court double booking rejected',pg_temp.denied(format('select public.league_command(%L,''draft_schedule'',%L::jsonb)',l,jsonb_build_object('base_revision',s#>'{league,revision}','data_revision',s#>'{league,data_revision}','explanation','Invalid collision','fixtures',bad)),'conflict'));
 bad:=locked||jsonb_build_array(jsonb_set(jsonb_set(future->0,'{starts_at}',to_jsonb('2099-01-01T01:00:00Z'::text)),'{ends_at}',to_jsonb('2099-01-01T02:00:00Z'::text)));
 perform pg_temp.ok('unconfirmed court time rejected',pg_temp.denied(format('select public.league_command(%L,''draft_schedule'',%L::jsonb)',l,jsonb_build_object('base_revision',s#>'{league,revision}','data_revision',s#>'{league,data_revision}','explanation','Invalid time','fixtures',bad)),'availability'));
 result:=public.league_command(l,'draft_schedule',jsonb_build_object('base_revision',s#>'{league,revision}','data_revision',s#>'{league,data_revision}','explanation','Integration test approved schedule','fixtures',fixtures));draft_id:=(result->>'id')::uuid;
 perform public.league_command(l,'publish_schedule',jsonb_build_object('version_id',draft_id));
 s:=public.league_snapshot(l,false);
 perform pg_temp.ok('published schedule revision',s#>>'{league,revision}'='2');
 perform pg_temp.ok('multi-team notifications queued',jsonb_array_length(s->'notifications')=12);
 perform pg_temp.ok('publication is idempotent',pg_temp.denied(format('select public.league_command(%L,''publish_schedule'',%L::jsonb)',l,jsonb_build_object('version_id',draft_id)),'Draft schedule not found'));
 queue:=public.league_command(l,'claim_notifications');perform pg_temp.ok('durable queue claims',jsonb_array_length(queue)=12);
 perform pg_temp.ok('concurrent claim does not duplicate',jsonb_array_length(public.league_command(l,'claim_notifications'))=0);
 perform public.league_command(l,'finish_notification',jsonb_build_object('notification_id',queue#>>'{0,id}','lease_id',queue#>>'{0,lease_id}','status','failed','error','Synthetic provider outage'));
 s:=public.league_snapshot(l,false);
 perform pg_temp.ok('notification failure retained for retry',exists(select 1 from jsonb_array_elements(s->'notifications') n where n->>'status'='failed' and n->>'attempts'='1'));
 -- Confirm and correct an existing historical game using synthetic private-upload metadata.
 select value into g from jsonb_array_elements(s->'games') where value->>'status'='confirmed' limit 1;
 perform set_config('test.game',g->>'id',true);perform set_config('test.home',g->>'home_team_id',true);perform set_config('test.away',g->>'away_team_id',true);
 perform set_config('test.rating',(select rating::text from public.teams where id=(g->>'home_team_id')::uuid),true);
 perform pg_temp.ok('scoresheet requires private upload',pg_temp.denied(format('select public.league_command(%L,''submit_scoresheet'',%L::jsonb)',l,jsonb_build_object('game_id',g->>'id','sha256',repeat('a',64),'storage_path','missing','source','manual','extraction','{}'::jsonb)),'Private scoresheet upload'));
end $$;
-- Only metadata is created within this rolled-back transaction, no uploaded photo is claimed.
reset role;
insert into storage.objects(bucket_id,name,owner_id) values('scoresheets',current_setting('test.league')||'/aa000000-0000-4000-8000-000000000001/test.png','aa000000-0000-4000-8000-000000000001');
set local role authenticated;
do $$declare l uuid:=current_setting('test.league')::uuid;g uuid:=current_setting('test.game')::uuid;sheet_id uuid;r jsonb;ex jsonb;old_rating int:=current_setting('test.rating')::int;v uuid;s jsonb;fixtures jsonb;begin
 ex:=jsonb_build_object('homeTeam',(select name from public.teams where id=current_setting('test.home')::uuid),'awayTeam',(select name from public.teams where id=current_setting('test.away')::uuid),'homeScore',10,'awayScore',90,'confidence',1,'warnings','[]'::jsonb,'players','[]'::jsonb);
 r:=public.league_command(l,'submit_scoresheet',jsonb_build_object('game_id',g,'sha256',repeat('a',64),'storage_path',l::text||'/aa000000-0000-4000-8000-000000000001/test.png','source','manual','extraction',ex));sheet_id:=(r->>'id')::uuid;
 perform pg_temp.ok('duplicate scoresheet blocked',pg_temp.denied(format('select public.league_command(%L,''submit_scoresheet'',%L::jsonb)',l,jsonb_build_object('game_id',g,'sha256',repeat('a',64),'storage_path',l::text||'/aa000000-0000-4000-8000-000000000001/test.png','source','manual','extraction',ex)),'duplicate key'));
 perform pg_temp.ok('result requires human confirmation',pg_temp.denied(format('select public.league_command(%L,''confirm_result'',%L::jsonb)',l,jsonb_build_object('sheet_id',sheet_id,'extraction',ex,'reviewed',false,'correction_reason','Synthetic correction')),'Human review'));
 perform pg_temp.ok('result correction requires reason',pg_temp.denied(format('select public.league_command(%L,''confirm_result'',%L::jsonb)',l,jsonb_build_object('sheet_id',sheet_id,'extraction',ex,'reviewed',true)),'correction reason'));
 perform pg_temp.ok('missing scores cannot be confirmed',pg_temp.denied(format('select public.league_command(%L,''confirm_result'',%L::jsonb)',l,jsonb_build_object('sheet_id',sheet_id,'extraction',ex||'{"homeScore":null}'::jsonb,'reviewed',true,'correction_reason','Synthetic correction')),'Both valid final scores'));
 perform pg_temp.ok('wrong AI team names cannot be confirmed',pg_temp.denied(format('select public.league_command(%L,''confirm_result'',%L::jsonb)',l,jsonb_build_object('sheet_id',sheet_id,'extraction',ex||'{"homeTeam":"Invented"}'::jsonb,'reviewed',true,'correction_reason','Synthetic correction')),'do not match'));
 perform public.league_command(l,'confirm_result',jsonb_build_object('sheet_id',sheet_id,'extraction',ex,'reviewed',true,'correction_reason','Synthetic test result correction'));
 perform pg_temp.ok('result correction updates official score',(select home_score=10 and away_score=90 from public.games where id=g));
 perform pg_temp.ok('ratings recomputed after correction',(select rating<>old_rating from public.teams where id=current_setting('test.home')::uuid));
 perform pg_temp.ok('missing stats stay absent',(select count(*)=0 from public.player_statistics where game_id=g));
 perform pg_temp.ok('same review cannot confirm twice',pg_temp.denied(format('select public.league_command(%L,''confirm_result'',%L::jsonb)',l,jsonb_build_object('sheet_id',sheet_id,'extraction',ex,'reviewed',true,'correction_reason','Synthetic correction')),'already reviewed'));
 perform pg_temp.ok('result invalidates pending recommendations',not exists(select 1 from public.division_proposals where league_id=l and status='pending'));
 perform pg_temp.ok('official result correction is permanently audited',(select count(*)=1 from public.result_revisions where game_id=g and reason='Synthetic test result correction'));
 perform pg_temp.ok('reopening requires a correction reason',pg_temp.denied(format('select public.league_command(%L,''reopen_result'',%L::jsonb)',l,jsonb_build_object('sheet_id',sheet_id)),'correction reason'));
 perform public.league_command(l,'reopen_result',jsonb_build_object('sheet_id',sheet_id,'correction_reason','Review the same original photo'));
 perform pg_temp.ok('reopening preserves the official score',(select home_score=10 and away_score=90 from public.games where id=g));
 perform public.league_command(l,'reject_scoresheet',jsonb_build_object('sheet_id',sheet_id));
 perform pg_temp.ok('rejected correction restores confirmed sheet',(select status='confirmed' and not reopened from public.scoresheets where id=sheet_id));
 perform public.league_command(l,'reopen_result',jsonb_build_object('sheet_id',sheet_id,'correction_reason','Fix a transcription error'));
 ex:=ex||'{"homeScore":20,"awayScore":80}'::jsonb;
 perform public.league_command(l,'confirm_result',jsonb_build_object('sheet_id',sheet_id,'extraction',ex,'reviewed',true,'correction_reason','Fix a transcription error from original photo'));
 perform pg_temp.ok('same original photo supports reviewed corrections',(select home_score=20 and away_score=80 from public.games where id=g));
 perform pg_temp.ok('original extraction is preserved',(select original_extraction->>'homeScore'='10' and extraction->>'homeScore'='20' from public.scoresheets where id=sheet_id));
 perform pg_temp.ok('correction history retains both decisions',(select count(*)=2 from public.result_revisions where game_id=g));
 perform public.league_command(l,'propose_balance');
 s:=public.league_snapshot(l,false);
 select value into r from jsonb_array_elements(s->'proposals') where value->>'status'='pending' and value->>'team_id'=(select value->>'id' from jsonb_array_elements(s->'teams') where value->>'name'='Eastside Eagles') limit 1;
 perform pg_temp.ok('division move has verified proposal',r is not null);
 perform public.league_command(l,'decide_proposal',jsonb_build_object('proposal_id',r->>'id','approve',true));
 perform pg_temp.ok('approved division adjustment persists',(select division_id=(r->>'to_division_id')::uuid from public.teams where id=(r->>'team_id')::uuid));
 s:=public.league_snapshot(l,false);
 perform pg_temp.ok('approved move does not auto-publish',(s#>>'{league,revision}')::int=2);
 select jsonb_agg(f) into fixtures from jsonb_array_elements(s->'fixtures') f where f->>'version_id'=(select value->>'id' from jsonb_array_elements(s->'versions') where value->>'status'='published');
 perform pg_temp.ok('old cross-division fixtures cannot be republished',pg_temp.denied(format('select public.league_command(%L,''draft_schedule'',%L::jsonb)',l,jsonb_build_object('base_revision',s#>'{league,revision}','data_revision',s#>'{league,data_revision}','explanation','Old pairs after approved move','fixtures',fixtures)),'same division'));
 -- Retain frozen historical fixtures and deterministically pair teams inside their new divisions.
 select jsonb_agg(f) into fixtures from jsonb_array_elements(s->'fixtures') f where f->>'version_id'=(select value->>'id' from jsonb_array_elements(s->'versions') where value->>'status'='published') and exists(select 1 from jsonb_array_elements(s->'games') gg where gg->>'id'=f->>'game_id' and gg->>'status'='confirmed');
 with ranked as(select id,division_id,row_number() over(partition by division_id order by id) as rn from public.teams where league_id=l and status='approved'), pairs as(select a.id home,b.id away,a.rn,a.division_id from ranked a join ranked b on a.division_id=b.division_id and a.rn%2=1 and b.rn=a.rn+1), numbered as(select *,row_number() over(order by division_id,rn) ix from pairs)
 select fixtures||jsonb_agg(jsonb_build_object('game_id',gen_random_uuid(),'home_team_id',home,'away_team_id',away,'court_id',(select id from public.courts where league_id=l order by id limit 1),'starts_at',date_trunc('day',now())+interval '3 days 13 hours'+make_interval(hours=>ix::int),'ends_at',date_trunc('day',now())+interval '3 days 14 hours'+make_interval(hours=>ix::int))) into fixtures from numbered;
 r:=public.league_command(l,'draft_schedule',jsonb_build_object('base_revision',s#>'{league,revision}','data_revision',s#>'{league,data_revision}','explanation','Regenerated after approved division adjustment','fixtures',fixtures));v:=(r->>'id')::uuid;
 perform public.league_command(l,'publish_schedule',jsonb_build_object('version_id',v));
 perform pg_temp.ok('revised schedule publishes after human approval',(public.league_snapshot(l,false)#>>'{league,revision}')::int=3);
 perform pg_temp.ok('revised schedule preserves confirmed games',(select count(*)=18 from public.fixtures f join public.games gg on gg.id=f.game_id where f.version_id=v and gg.status='confirmed'));
 perform pg_temp.ok('revised publication creates affected coach updates',jsonb_array_length(public.league_snapshot(l,false)->'notifications')>12);
 perform public.reserve_ai(l,'integration_test');
 perform pg_temp.ok('AI reservations persisted',(select count(*)=1 from public.ai_requests where league_id=l));
 perform set_config('request.jwt.claims','{"sub":"aa000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
 perform pg_temp.ok('cross-tenant snapshot denied',pg_temp.denied(format('select public.league_snapshot(%L,false)',l),'access denied'));
 perform pg_temp.ok('cross-tenant mutation denied',pg_temp.denied(format('select public.league_command(%L,''propose_balance'',''{}'')',l),'Administrator required'));
 perform pg_temp.ok('cross-tenant RLS hides tables',(select count(*)=0 from public.teams where league_id=l));
end $$;
reset role;
select set_config('request.jwt.claims','{"role":"anon"}',true);
set local role anon;
do $$declare p jsonb;l uuid;begin
 select id into l from public.public_leagues() where is_demo limit 1;p:=public.league_snapshot(l,true);
 perform pg_temp.ok('public privacy excludes player and contact information',jsonb_array_length(p->'players')=0 and jsonb_array_length(p->'scoresheets')=0 and not(p::text like '%coach_email%') and not(p::text like '%birth_date%') and not(p::text like '%storage_path%'));
 perform pg_temp.ok('anonymous mutation denied',pg_temp.denied(format('select public.league_command(%L,''propose_balance'',''{}'')',l),'permission denied'));
 perform pg_temp.ok('anonymous direct tables denied',pg_temp.denied('select * from public.players','permission denied'));
 perform pg_temp.ok('public versions omit approving account identifiers',not(p::text like '%approved_by%') and not(p::text like '%created_by%'));
 perform pg_temp.ok('private storage is not public',(select count(*)=0 from storage.objects));
end $$;
reset role;
select jsonb_build_object('passed',(select count(*) from assertions where passed),'tests',(select jsonb_agg(name order by name) from assertions)) as test_results;
rollback;
